(()=>{const URL=window.APP_CONFIG?.supabaseUrl||"https://gzdusguveeeflmlvvmwe.supabase.co";const KEY=window.APP_CONFIG?.supabasePublishableKey||"sb_publishable_nSqPHZf1-1CAJMFNmrpNqA_lafobeV-";const sb=window.supabase?.createClient?.(URL,KEY);const esc=s=>String(s??"").replace(/[&<>"]/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[m]));const fmt=d=>new Date(d).toLocaleDateString("id-ID",{day:"2-digit",month:"short",year:"numeric"}).toUpperCase();const fallback=[["digitalisasi-desa-bukan-sekadar-teknologi","DESA","Digitalisasi desa bukan sekadar teknologi. Ia tentang membuat layanan terasa lebih dekat.","29 SEP 2026","4"],["umkm-lokal-menemukan-ruang-baru-untuk-tumbuh","EKONOMI","UMKM lokal menemukan ruang baru untuk tumbuh.","28 SEP 2026","4"],["gotong-royong-menjadi-agenda-bersama-warga","KOMUNITAS","Gotong royong menjadi agenda bersama warga.","27 SEP 2026","3"],["informasi-pelayanan-desa-kini-lebih-mudah-ditemukan","LAYANAN","Informasi pelayanan desa kini lebih mudah ditemukan.","26 SEP 2026","3"]];function card(x,i){const slug=esc(x.slug),cat=esc(x.category),title=esc(x.title),date=fmt(x.published_at),mins=esc(x.reading_minutes);if(i===0)return '<div class="col-lg-7"><article class="news-feature news-clickable" data-news-slug="'+slug+'" tabindex="0"><div class="news-photo photo-village"><span class="news-tag">'+cat+'</span></div><div class="news-feature-copy"><small>'+date+' · '+mins+' MIN BACA</small><h3>'+title+'</h3><p>'+esc(x.excerpt||"")+'</p><span class="news-action">Baca selengkapnya <i class="bi bi-arrow-up-right"></i></span></div></article></div>';const photos=["photo-umkm","photo-community","photo-service"];return '<article class="news-row news-clickable" data-news-slug="'+slug+'" tabindex="0"><div class="mini-photo '+photos[i-1]+'"></div><div><span>'+cat+'</span><h4>'+title+'</h4><small>'+date+'</small></div></article>'}async function load(){const box=document.getElementById("newsLiveGrid");if(!box)return;let rows=[];try{if(!sb)throw new Error("Supabase unavailable");const r=await sb.from("news_syndication_feed").select("slug,title,excerpt,category,reading_minutes,published_at,image_key").lte("published_at",new Date().toISOString()).order("published_at",{ascending:false}).limit(4);if(r.error)throw r.error;rows=r.data||[]}catch(e){console.warn("Kabar Desa fallback:",e);rows=fallback.map(a=>({slug:a[0],category:a[1],title:a[2],published_at:new Date(a[3]+" 2026"),reading_minutes:a[4]}))}if(!rows.length){box.innerHTML='<div class="col-12"><div class="modal-note">Belum ada berita yang diterbitkan.</div></div>';return;}if(rows.length){const first=card(rows[0],0), rest=rows.slice(1).map((x,i)=>card(x,i+1)).join("");box.innerHTML=first+'<div class="col-lg-5 d-flex flex-column gap-3">'+rest+'</div>'}bind()}function go(slug){window.location.href="./berita.html?slug="+encodeURIComponent(slug)}function bind(){document.querySelectorAll(".news-clickable").forEach(el=>{el.addEventListener("click",()=>go(el.dataset.newsSlug));el.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();go(el.dataset.newsSlug)}})});document.querySelector("[data-news-all]")?.addEventListener("click",e=>{e.preventDefault();window.location.href="./berita.html"})}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",load,{once:true});else load()})();